/** The rules that the definitions apply, and the rules that a scenario breaks */
export interface CoverageFacts {
  /** Rules of definitions */
  readonly applied_rules: RulePlaces;
  /** Rules of definitions */
  readonly broken_rules: RulePlaces;
}

/** The rules that no scenario breaks, each once */
export type UncoveredRules = readonly RulePlace[];

/** The rules that gate 3 reports as uncovered-rule */
export interface RulesFound {
  /** The rules that no scenario breaks, each once */
  readonly uncovered_rules: UncoveredRules;
}

/** A manifest, the contract of a domain: its header, and its definitions, rules and operations by name */
export interface Manifest {
  /** The header of a manifest, which names the domain and its version */
  readonly manifest: ManifestHeader;
  /** The definitions of a manifest, by name */
  readonly definitions?: DefinitionDeclarations;
  /** The rules of a manifest, by name */
  readonly rules?: RuleDeclarations;
  /** The operations of a manifest, by name */
  readonly operations?: OperationDeclarations;
}

/** The header of a manifest, which names the domain and its version */
export interface ManifestHeader {
  /** The namespace of a manifest, which is also the namespace of its URNs */
  readonly namespace: NamespaceName;
  /** The domain of a manifest, such as booking */
  readonly domain: DomainName;
  /** A semver version of a manifest, such as 1.4.0 or 2.0.0-alpha.1, with the pattern that the manifest reader checks */
  readonly version: Version;
  /** What the callers of the domain do with a part that they do not know */
  readonly compatibility?: Compatibility;
}

/** What the callers of the domain do with a part that they do not know */
export interface Compatibility {
  /** ignore-unknown: the callers ignore a property or an output that they do not know, so a new one is compatible */
  readonly callers: Callers;
}

/** ignore-unknown: the callers ignore a property or an output that they do not know, so a new one is compatible */
export type Callers = "ignore-unknown";

/** What a part is, for a reader of the manifest: text with a character that is not a space */
export type Description = string;

/** True when the part is deprecated: it still works, and each use of it in a live part gives a warning */
export type Deprecated = boolean;

/** The definitions of a manifest, by name */
export type DefinitionDeclarations = { readonly [key: string]: DefinitionDeclaration };

/** A definition: the structure of a value, and the rules that each value keeps */
export interface DefinitionDeclaration {
  /** What a part is, for a reader of the manifest: text with a character that is not a space */
  readonly description: Description;
  /** The type of a definition - string, number, integer, boolean, object, array, map or union, or the name of another definition, whose structure it has */
  readonly type: TypeReference;
  /** The properties of an object, in their order */
  readonly properties?: PropertyEntries;
  /** The name of a definition of a manifest, in lowercase snake_case, such as party_size */
  readonly items?: DefinitionNameValue;
  /** The name of a definition of a manifest, in lowercase snake_case, such as party_size */
  readonly values?: DefinitionNameValue;
  /** The name of a definition of a manifest, in lowercase snake_case, such as party_size */
  readonly keys?: DefinitionNameValue;
  /** The name of a property of an object */
  readonly tag?: PropertyName;
  /** The variants of a union: a list of definitions of different JSON types, or, with a tag, each value of the tag to its object variant */
  readonly variants?: Variants;
  /** The name of a property of an object */
  readonly identifier?: PropertyName;
  /** The rules that a part applies, by name, in their order */
  readonly rules?: RuleUses;
  /** True when the part is deprecated: it still works, and each use of it in a live part gives a warning */
  readonly deprecated?: Deprecated;
}

/** The type of a definition - string, number, integer, boolean, object, array, map or union, or the name of another definition, whose structure it has */
export type TypeReference = string;

/** The name of a property of an object */
export type PropertyName = string;

/** The properties of an object, in their order */
export type PropertyEntries = readonly PropertyEntry[];

/** A property: the name of its definition, or a name with its own definition */
export type PropertyEntry = DefinitionNameValue | PropertyWithDefinition;

/** A property with its own definition, such as { address: street_address } in YAML flow form */
export type PropertyWithDefinition = { readonly [key: string]: DefinitionNameValue };

/** The variants of a union: a list of definitions of different JSON types, or, with a tag, each value of the tag to its object variant */
export type Variants = VariantList | TaggedVariants;

/** The variants of a union with no tag, at most one of each JSON type */
export type VariantList = readonly DefinitionNameValue[];

/** The variants of a union with a tag: each value of the tag to its object variant */
export type TaggedVariants = { readonly [key: string]: DefinitionNameValue };

/** The rules that a part applies, by name, in their order */
export type RuleUses = readonly RuleUse[];

/** A rule applied by name: the name alone, or the name with its argument */
export type RuleUse = RuleUseName | RuleWithArgument;

/** The name of a rule in a use: a rule of the manifest, or a standard rule, whose names are camelCase */
export type RuleUseName = string;

/** A rule with its argument, such as minimum: 1, or between: { low: 1, high: 9 } */
export type RuleWithArgument = { readonly [key: string]: JsonValue };

/** Any JSON value but null: the argument of a rule use, or the value of an answer */
export type JsonValue = JsonString | JsonNumber | JsonFlag | JsonList | JsonMap;

/** A JSON value that is a string */
export type JsonString = string;

/** A JSON value that is a number */
export type JsonNumber = number;

/** A JSON value that is true or false */
export type JsonFlag = boolean;

/** A JSON value that is a list */
export type JsonList = readonly JsonValue[];

/** A JSON value that is a map, such as the arguments of the parameters of a rule by name */
export type JsonMap = { readonly [key: string]: JsonValue };

/** The rules of a manifest, by name */
export type RuleDeclarations = { readonly [key: string]: RuleDeclaration };

/** The name of a rule of a manifest, in lowercase snake_case */
export type RuleName = string;

/** A rule: an expression of the rule language, its parameters, and what its failure says */
export interface RuleDeclaration {
  /** What a part is, for a reader of the manifest: text with a character that is not a space */
  readonly description: Description;
  /** The parameters of a rule, in their order */
  readonly parameters?: ParameterNames;
  /** An expression of the rule language that gives true when the value keeps the rule */
  readonly rule: RuleText;
  /** What a failure of a rule says, with each argument in braces, such as Must be at least {bound} */
  readonly failure_message: FailureText;
  /** True when the part is deprecated: it still works, and each use of it in a live part gives a warning */
  readonly deprecated?: Deprecated;
}

/** An expression of the rule language that gives true when the value keeps the rule */
export type RuleText = string;

/** The operations of a manifest, by name */
export type OperationDeclarations = { readonly [key: string]: OperationDeclaration };

/** The name of an operation of a manifest, in lowercase snake_case */
export type OperationNameValue = string;

/** An operation: its input, its outputs, and the rules of each answer */
export interface OperationDeclaration {
  /** What a part is, for a reader of the manifest: text with a character that is not a space */
  readonly description: Description;
  /** The name of a definition of a manifest, in lowercase snake_case, such as party_size */
  readonly input: DefinitionNameValue;
  /** The outputs of an operation: the core answers exactly one of them */
  readonly output: OutputEntries;
  /** The rules that a part applies, by name, in their order */
  readonly rules?: RuleUses;
  /** True when the part is deprecated: it still works, and each use of it in a live part gives a warning */
  readonly deprecated?: Deprecated;
}

/** The outputs of an operation: the core answers exactly one of them */
export type OutputEntries = readonly OutputEntry[];

/** An output: the name of its object, or the name with the rules of the output */
export type OutputEntry = DefinitionNameValue | OutputWithRules;

/** An output with its rules, such as booked: [deposit_paid] */
export type OutputWithRules = { readonly [key: string]: RuleUses };

/** A rule that a value breaks: the definition or the operation of the rule, the rule, the place of the value, and the failure message */
export interface FailureValue {
  /** The name of a part; a standard rule has a camelCase name, such as minLength */
  readonly definition: PartName;
  /** The name of a part; a standard rule has a camelCase name, such as minLength */
  readonly rule: PartName;
  /** The place of a value in the value that is checked, such as contact.email or dishes[0].amount, or empty for the whole value */
  readonly path: ValuePath;
  /** What a failure of a rule says, with each argument in braces, such as Must be at least {bound} */
  readonly failure_message: FailureText;
}

/** The place of a value in the value that is checked, such as contact.email or dishes[0].amount, or empty for the whole value */
export type ValuePath = string;

/** The rules that a value breaks, one or more */
export type Failures = readonly FailureValue[];

/** True: the value keeps the contract */
export type Accepted = boolean;

/** False: the value breaks the contract */
export type Refused = boolean;

/** The result of check for a value that keeps each rule of its definition */
export interface CheckAccepted {
  /** True: the value keeps the contract */
  readonly ok: Accepted;
  /** The URN of a part, such as urn:demo:booking:definition:party_size */
  readonly domain: Urn;
  /** Any JSON value but null: the argument of a rule use, or the value of an answer */
  readonly value: JsonValue;
}

/** The result of check for a value that breaks a rule of its definition */
export interface CheckRefused {
  /** False: the value breaks the contract */
  readonly ok: Refused;
  /** The URN of a part, such as urn:demo:booking:definition:party_size */
  readonly domain: Urn;
  /** The rules that a value breaks, one or more */
  readonly failures: Failures;
}

/** The result of runOperation when the input and the answer keep the contract: the answer of the core, its output and its value */
export interface CallAnswered {
  /** True: the value keeps the contract */
  readonly ok: Accepted;
  /** The URN of a part, such as urn:demo:booking:definition:party_size */
  readonly domain: Urn;
  /** The name of an operation of a manifest, in lowercase snake_case */
  readonly operation: OperationNameValue;
  /** The name of a definition of a manifest, in lowercase snake_case, such as party_size */
  readonly output: DefinitionNameValue;
  /** Any JSON value but null: the argument of a rule use, or the value of an answer */
  readonly value: JsonValue;
}

/** The result of runOperation when the input or the answer breaks the contract, by its kind */
export type CallRefused = InputRejected | ContractViolation;

/** Why a call is refused - InputRejected, the caller sent an input that breaks the contract, so the core did not run; or ContractViolation, the core answered what the contract does not allow, which is a bug in the core */
export type RefusalKind = "InputRejected" | "ContractViolation";

/** A call whose input breaks the contract; the core did not run */
export interface InputRejected {
  /** False: the value breaks the contract */
  readonly ok: Refused;
  /** The URN of a part, such as urn:demo:booking:definition:party_size */
  readonly domain: Urn;
  /** The name of an operation of a manifest, in lowercase snake_case */
  readonly operation: OperationNameValue;
  /** Why a call is refused - InputRejected, the caller sent an input that breaks the contract, so the core did not run; or ContractViolation, the core answered what the contract does not allow, which is a bug in the core */
  readonly kind: RefusalKind;
  /** The rules that a value breaks, one or more */
  readonly failures: Failures;
}

/** A call whose answer breaks the contract, which is a bug in the core */
export interface ContractViolation {
  /** False: the value breaks the contract */
  readonly ok: Refused;
  /** The URN of a part, such as urn:demo:booking:definition:party_size */
  readonly domain: Urn;
  /** The name of an operation of a manifest, in lowercase snake_case */
  readonly operation: OperationNameValue;
  /** Why a call is refused - InputRejected, the caller sent an input that breaks the contract, so the core did not run; or ContractViolation, the core answered what the contract does not allow, which is a bug in the core */
  readonly kind: RefusalKind;
  /** The rules that a value breaks, one or more */
  readonly failures: Failures;
}

/** A problem that a command found: its code, its severity, its place, what it says, and its fix */
export interface Problem {
  /** A code of a problem that urn-forge reports. A tool or an agent acts on the code, not on the message. The meaning, the severity and the fix of each code are the argument of is_the_code, in the operation fix_of; the codes of each gate are the argument of reports_its_codes, in the operation judge_gate */
  readonly code: Code;
  /** Whether a problem fails its gate (error) or only shows it (warning) */
  readonly severity: Severity;
  /** A file, relative to the folder of the command, with forward slashes */
  readonly file?: FilePath;
  /** A line of a file, from 1 */
  readonly line?: LineNumber;
  /** The place of a problem in the manifest or the config, as a list of keys, such as definitions, party_size, rules, 0 */
  readonly path?: ProblemPath;
  /** The URN of a part, such as urn:demo:booking:definition:party_size */
  readonly domain?: Urn;
  /** What a problem says */
  readonly message: ProblemMessage;
  /** What to do about each case of a code, in one sentence */
  readonly fix: Fix;
}

/** The problems of a command, in the order it found them */
export type Problems = readonly Problem[];

/** A file, relative to the folder of the command, with forward slashes */
export type FilePath = string;

/** A line of a file, from 1 */
export type LineNumber = number;

/** The place of a problem in the manifest or the config, as a list of keys, such as definitions, party_size, rules, 0 */
export type ProblemPath = readonly PathKey[];

/** A key of a place: the name of a key of a map, or the index of an item of a list */
export type PathKey = KeyName | KeyIndex;

/** The name of a key of a map */
export type KeyName = string;

/** The index of an item of a list, from 0 */
export type KeyIndex = number;

/** What a problem says */
export type ProblemMessage = string;

/** True when the command passed: its exit code is 0 */
export type Passed = boolean;

/** The report of compile --format json: the files that it wrote or removed, and its problems */
export interface CompileReport {
  /** True when the command passed: its exit code is 0 */
  readonly ok: Passed;
  /** The generated files of compile, for each domain */
  readonly files?: WrittenFiles;
  /** The problems of a command, in the order it found them */
  readonly problems: Problems;
}

/** The generated files of compile, for each domain */
export type WrittenFiles = readonly WrittenFile[];

/** A generated file, and what compile did with it */
export interface WrittenFile {
  /** The URN of a part, such as urn:demo:booking:definition:party_size */
  readonly domain: Urn;
  /** What compile did with a generated file: wrote it, found it unchanged, or removed it because no domain gives it */
  readonly status: WriteStatus;
  /** A file, relative to the folder of the command, with forward slashes */
  readonly path: FilePath;
}

/** What compile did with a generated file: wrote it, found it unchanged, or removed it because no domain gives it */
export type WriteStatus = "wrote" | "unchanged" | "removed";

/** The report of verify --format json: each gate of each domain, the count of warnings, and the problems */
export interface VerifyReport {
  /** True when the command passed: its exit code is 0 */
  readonly ok: Passed;
  /** The outcomes of the gates, of each domain in turn */
  readonly gates?: GateReports;
  /** The outcomes of the gates, by domain */
  readonly domains?: DomainReports;
  /** The number of problems that are warnings */
  readonly warnings?: WarningCount;
  /** The problems of a command, in the order it found them */
  readonly problems: Problems;
}

/** The outcome of a gate: its number, its name, whether it passed, and its summary */
export interface GateReport {
  /** The URN of a part, such as urn:demo:booking:definition:party_size */
  readonly domain?: Urn;
  /** The number of a gate of verify, from 1 to 5 */
  readonly gate: GateNumber;
  /** The name of a gate, as verify prints it. What makes each gate fail, and its codes, are the argument of reports_its_codes, in the operation judge_gate */
  readonly name: GateName;
  /** True when the command passed: its exit code is 0 */
  readonly pass: Passed;
  /** What a gate checked, in one line, such as 1 generated file(s) compared byte for byte */
  readonly summary: GateSummary;
}

/** The outcomes of the gates, of each domain in turn */
export type GateReports = readonly GateReport[];

/** What a gate checked, in one line, such as 1 generated file(s) compared byte for byte */
export type GateSummary = string;

/** The outcomes of the gates of one domain */
export interface DomainReport {
  /** The URN of a part, such as urn:demo:booking:definition:party_size */
  readonly urn: Urn;
  /** The outcomes of the gates, of each domain in turn */
  readonly gates: GateReports;
}

/** The outcomes of the gates, by domain */
export type DomainReports = readonly DomainReport[];

/** The number of problems that are warnings */
export type WarningCount = number;

/** The report of diff --format json: the versions, each change with its class, and whether the versions allow the breaking changes */
export interface DiffReport {
  /** True when the command passed: its exit code is 0 */
  readonly ok: Passed;
  /** The version of the old manifest */
  readonly from?: FromVersion;
  /** The version of the new manifest */
  readonly to?: ToVersion;
  /** The number of changes that are breaking */
  readonly breaking?: BreakingCount;
  /** The changes from the old manifest to the new one */
  readonly changes?: Changes;
  /** True when the versions allow the breaking changes, or when no change is breaking */
  readonly allowed?: BreakingAllowedFlag;
  /** Why the versions allow a breaking change or not */
  readonly why?: Reason;
  /** The problems of a command, in the order it found them */
  readonly problems: Problems;
}

/** The number of changes that are breaking */
export type BreakingCount = number;

/** True when the versions allow the breaking changes, or when no change is breaking */
export type BreakingAllowedFlag = boolean;

/** The changes from the old manifest to the new one */
export type Changes = readonly Change[];

/** A change of a part: its class, the URN of the part, and what changed */
export interface Change {
  /** Whether a change can break a caller (breaking) or not (compatible) */
  readonly class: ChangeClass;
  /** The URN of a part, such as urn:demo:booking:definition:party_size */
  readonly place: Urn;
  /** What a problem says */
  readonly message: ProblemMessage;
}

/** Whether a change can break a caller (breaking) or not (compatible) */
export type ChangeClass = "breaking" | "compatible";

/** A code of a problem that urn-forge reports. A tool or an agent acts on the code, not on the message. The meaning, the severity and the fix of each code are the argument of is_the_code, in the operation fix_of; the codes of each gate are the argument of reports_its_codes, in the operation judge_gate */
function check_code(value: any, path: string, failures: Failure[]): boolean {
  if (!(typeof value === 'string')) { failures.push({ definition: "code", rule: 'type', path, failure_message: "Must be a string" }); return false; }
  let held = true;
  if (!$holds(() => $in(value, ["usage","config-unreadable","config-invalid","manifest-unreadable","yaml-syntax","manifest-shape","unknown-definition","type-cycle","duplicate-property","unknown-property","not-an-object","duplicate-output","invalid-identifier","deprecated-use","standard-name","unknown-rule","rule-argument","rule-syntax","rule-type","rule-guard","rule-scope","invalid-message","tsconfig-unreadable","core-not-found","type-error","core-not-satisfying","direct-call","suppressed-check","feature-syntax","unknown-name","uncovered-operation","uncovered-output","uncovered-variant","uncovered-rule","drift","base-unreadable","removed-rule","wider-rule","removed-output","removed-scenario","internal-contract"]))) { failures.push({ definition: "code", rule: "enum", path, failure_message: "Must be one of usage, config-unreadable, config-invalid, manifest-unreadable, yaml-syntax, manifest-shape, unknown-definition, type-cycle, duplicate-property, unknown-property, not-an-object, duplicate-output, invalid-identifier, deprecated-use, standard-name, unknown-rule, rule-argument, rule-syntax, rule-type, rule-guard, rule-scope, invalid-message, tsconfig-unreadable, core-not-found, type-error, core-not-satisfying, direct-call, suppressed-check, feature-syntax, unknown-name, uncovered-operation, uncovered-output, uncovered-variant, uncovered-rule, drift, base-unreadable, removed-rule, wider-rule, removed-output, removed-scenario, internal-contract" }); held = false; }
  return held;
}

/** What to do about each case of a code, in one sentence */
function check_fix(value: any, path: string, failures: Failure[]): boolean {
  if (!(typeof value === 'string')) { failures.push({ definition: "fix", rule: 'type', path, failure_message: "Must be a string" }); return false; }
  let held = true;
  if (!$holds(() => (($size(value) as any) >= (1 as any)))) { failures.push({ definition: "fix", rule: "minLength", path, failure_message: "Must have at least 1 characters" }); held = false; }
  return held;
}

/** What a code means, the same for each case of the code */
function check_code_meaning(value: any, path: string, failures: Failure[]): boolean {
  if (!(typeof value === 'string')) { failures.push({ definition: "code_meaning", rule: 'type', path, failure_message: "Must be a string" }); return false; }
  let held = true;
  if (!$holds(() => $matches(value, "\\S"))) { failures.push({ definition: "code_meaning", rule: "pattern", path, failure_message: "Must match \\S" }); held = false; }
  return held;
}

/** The severity of each problem of a code: error, warning, or by-version for the codes of gate 5 that a new version can allow, which are a warning when the version allows the change and an error when it does not */
function check_code_severity(value: any, path: string, failures: Failure[]): boolean {
  if (!(typeof value === 'string')) { failures.push({ definition: "code_severity", rule: 'type', path, failure_message: "Must be a string" }); return false; }
  let held = true;
  if (!$holds(() => $in(value, ["error","warning","by-version"]))) { failures.push({ definition: "code_severity", rule: "enum", path, failure_message: "Must be one of error, warning, by-version" }); held = false; }
  return held;
}

/** What a code is: what it means, its severity and its fix */
function check_code_entry(value: any, path: string, failures: Failure[]): boolean {
  if (!$isObject(value)) { failures.push({ definition: "code_entry", rule: 'type', path, failure_message: "Must be an object" }); return false; }
  let ok = true;
  let missing = false;
  if (value["meaning"] === undefined) missing = true;
  else if (!check_code_meaning(value["meaning"], $at(path, "meaning"), failures)) ok = false;
  if (value["severity"] === undefined) missing = true;
  else if (!check_code_severity(value["severity"], $at(path, "severity"), failures)) ok = false;
  if (value["fix"] === undefined) missing = true;
  else if (!check_fix(value["fix"], $at(path, "fix"), failures)) ok = false;
  if (missing) { failures.push({ definition: "code_entry", rule: 'required', path, failure_message: "Must have meaning, severity, fix" }); ok = false; }
  for (const key of Object.keys(value)) if (!["meaning","severity","fix"].includes(key)) { failures.push({ definition: "code_entry", rule: 'properties', path: $at(path, key), failure_message: "Must be one of the properties of code_entry: meaning, severity, fix" }); ok = false; }
  if (!ok) return false;
  return true;
}

/** Each code, and what it is */
function check_code_entries(value: any, path: string, failures: Failure[]): boolean {
  if (!$isObject(value)) { failures.push({ definition: "code_entries", rule: 'type', path, failure_message: "Must be a map" }); return false; }
  let ok = true;
  for (const [key, item] of Object.entries(value)) {
    if (!check_code(key, $at(path, key), failures)) ok = false;
    if (!check_code_entry(item, $at(path, key), failures)) ok = false;
  }
  if (!ok) return false;
  return true;
}

/** The name of a rule of the standard set, which a manifest uses with no declaration. The parameters and texts of each rule are the argument of is_the_standard_rule, in the operation describe_standard_rule */
function check_standard_rule_name(value: any, path: string, failures: Failure[]): boolean {
  if (!(typeof value === 'string')) { failures.push({ definition: "standard_rule_name", rule: 'type', path, failure_message: "Must be a string" }); return false; }
  let held = true;
  if (!$holds(() => $in(value, ["enum","const","minimum","maximum","exclusiveMinimum","exclusiveMaximum","multipleOf","minLength","maxLength","pattern","format","minItems","maxItems","uniqueItems","required"]))) { failures.push({ definition: "standard_rule_name", rule: "enum", path, failure_message: "Must be one of enum, const, minimum, maximum, exclusiveMinimum, exclusiveMaximum, multipleOf, minLength, maxLength, pattern, format, minItems, maxItems, uniqueItems, required" }); held = false; }
  return held;
}

/** The name of a parameter of a rule, which is also the name of a definition of its argument */
function check_parameter_name(value: any, path: string, failures: Failure[]): boolean {
  if (!(typeof value === 'string')) { failures.push({ definition: "parameter_name", rule: 'type', path, failure_message: "Must be a string" }); return false; }
  let held = true;
  if (!$holds(() => $matches(value, "^[a-z][a-z0-9_]{0,62}$"))) { failures.push({ definition: "parameter_name", rule: "pattern", path, failure_message: "Must match ^[a-z][a-z0-9_]{0,62}$" }); held = false; }
  return held;
}

/** The parameters of a rule, in their order */
function check_parameter_names(value: any, path: string, failures: Failure[]): boolean {
  if (!Array.isArray(value)) { failures.push({ definition: "parameter_names", rule: 'type', path, failure_message: "Must be a list" }); return false; }
  let ok = true;
  for (const [i, item] of value.entries()) if (!check_parameter_name(item, $item(path, i), failures)) ok = false;
  if (!ok) return false;
  return true;
}

/** What a rule checks, and why */
function check_rule_description(value: any, path: string, failures: Failure[]): boolean {
  if (!(typeof value === 'string')) { failures.push({ definition: "rule_description", rule: 'type', path, failure_message: "Must be a string" }); return false; }
  let held = true;
  if (!$holds(() => (($size(value) as any) >= (1 as any)))) { failures.push({ definition: "rule_description", rule: "minLength", path, failure_message: "Must have at least 1 characters" }); held = false; }
  return held;
}

/** What a failure of a rule says, with each argument in braces, such as Must be at least {bound} */
function check_failure_text(value: any, path: string, failures: Failure[]): boolean {
  if (!(typeof value === 'string')) { failures.push({ definition: "failure_text", rule: 'type', path, failure_message: "Must be a string" }); return false; }
  let held = true;
  if (!$holds(() => (($size(value) as any) >= (1 as any)))) { failures.push({ definition: "failure_text", rule: "minLength", path, failure_message: "Must have at least 1 characters" }); held = false; }
  if (!$holds(() => $matches(value, "\\S"))) { failures.push({ definition: "failure_text", rule: "pattern", path, failure_message: "Must match \\S" }); held = false; }
  return held;
}

